#pragma once

// Original dqhud_droid touch-HUD layout (menu_HUD_2: fixed three skill buttons + faery + attack on the right, joystick on
// the left). Generated by features/hud_panels/export_touch_hud_v1.py from the exact SWF display lists; all values are in
// the authored 480x320 stage (twips / 20). A control's art lives in its own sprite-local space; the authored
// transform maps it to the stage as stage = local * scale + origin.

#include "../generic_skills/pc_gameplay_hud_button_art_v1.hpp"

#include <array>
#include <vector>

namespace dh::foundation::hud_panels {

using generic_skills::PcGameplayHudArtBatchV1;

struct TouchHudPlacementV1 {
    float scale{};
    float origin_x{};
    float origin_y{};
};

struct TouchHudAuthoredLayoutV1 {
    TouchHudPlacementV1 skill1, skill2, skill3;   // btn_skill1..3 (source slots 0, 1, 2)
    TouchHudPlacementV1 interact;                  // btn_interact (attack / context action)
    TouchHudPlacementV1 spell;                     // btn_spell (faery)
    TouchHudPlacementV1 potion;                    // HealthBars.btn_potion
    TouchHudPlacementV1 itunes;                    // itunes_controls.btn_itunes (music note)
    TouchHudPlacementV1 mainmenu;                  // btn_mainmenu (pause)
    TouchHudPlacementV1 charactermenu;             // btn_charactermenu (portrait)
    TouchHudPlacementV1 joystick;                  // Joystick (movement; deliberately not drawn)
    std::array<float, 4> potion_count_rect;        // x0, y0, x1, y1 of cnt.value in stage px (centred text)
    float potion_count_height;                     // source text height in stage px
    std::array<float, 4> joystick_zone;            // Joystick.stick.hitzone rectangle, x0, y0, x1, y1
    std::array<float, 2> potion_icon_offset;       // btn_potion.btframe offset; shape 105 (potion icon) is in btframe space
    std::array<float, 2> action_translate;         // btn_interact art generated at menu_HUD_0 -> menu_HUD_2
    std::array<float, 2> pause_translate;          // btn_mainmenu (pause_ui art, generated at menu_HUD_0) -> menu_HUD_2
};

const TouchHudAuthoredLayoutV1& touch_hud_authored_layout_v1() noexcept;
// btn_itunes idle frame, stage space (menu_HUD_2 placement).
const std::vector<PcGameplayHudArtBatchV1>& touch_music_button_v1() noexcept;

} // namespace dh::foundation::hud_panels
